import{_ as l,c as i,o,a4 as t,a9 as a,aa as e,ab as r,ac as s}from"./chunks/framework.CnbusAkP.js";const b=JSON.parse('{"title":"网络协议","description":"","frontmatter":{},"headers":[],"relativePath":"browser/浏览器工作原理/2_网络协议.md","filePath":"browser/浏览器工作原理/2_网络协议.md"}'),p={name:"browser/浏览器工作原理/2_网络协议.md"},c=t('<h1 id="网络协议" tabindex="-1">网络协议 <a class="header-anchor" href="#网络协议" aria-label="Permalink to &quot;网络协议&quot;">​</a></h1><h2 id="tcp-ip协议" tabindex="-1">TCP/IP协议 <a class="header-anchor" href="#tcp-ip协议" aria-label="Permalink to &quot;TCP/IP协议&quot;">​</a></h2><p>不管是HTTP还是WebSocket，都是基于TCP/IP协议的</p><h3 id="一个数据包的传输" tabindex="-1">一个数据包的传输 <a class="header-anchor" href="#一个数据包的传输" aria-label="Permalink to &quot;一个数据包的传输&quot;">​</a></h3><p>互联网中文件会被拆分为很多小的数据包来传输</p><p><img src="'+a+'" alt="案例"></p><p><strong>数据是如何被完整地送达应用程序</strong></p><ul><li>数据包传输要符合IP协议标准（网络层）</li><li>A主机中，数据包在传输层附加TCP头（端口号、数据包序列号），组成新的TCP数据包，再交给网络层</li><li>网络层附加IP头（IP地址等信息）到TCP数据包上，组成新的IP数据包，交给底层</li><li>B主机接收到数据包，在网络层拆开IP头信息，交给传输层</li><li>传输层把TCP头拆开，根据端口号，把数据交给上层应用程序</li></ul><p><strong>TCP和UDP</strong></p><p>在数据传输中，UDP和TCP的流程是一致的，都是<strong>在传输层把数据送达应用程序</strong>，它们不同点事：</p><ul><li>对于数据包丢失情况，UDP没有重发机制，TCP有重发机制，TCP更可靠</li><li>对于数据包完整性，UDP如果乱序了则不知道如何组合数据包还原完整文件，TCP有数据包排序机制可以把乱序数据包组合成一个完整文件</li><li>对于传输速度，UDP传输速度比TCP更快</li><li>所以UDP适合对数据完整性要求不严格的领域，比如视频、互动游戏；TCP适合对数据可靠性要求高的应用，比如邮件</li></ul><p><img src="'+e+'" alt="案例2"></p><p><strong>一个完整的TCP连接的生命周期包</strong></p><ul><li>建立连接阶段：通过三次握手建立客户端和服务器之间的连接。在数据包传输前先做好两段准备工作，三次握手就是建立一个TCP连接时，总共要发送三个数据包以确认连接的建立</li><li>传输数据阶段：接收端需要对每个数据包进行确认操作，也就是需要发送确认数据包给发送端。如果发送端没有收到确认数据则视为丢包，触发重发机制。数据包都到达接收端后会按照TCP头的序号进行排序，组成完整的数据</li><li>断开连接阶段：数据传输完毕之后，就要终止连接了，用四次挥手保证双方都能断开连接</li></ul><p>TCP为了保证数据传输的可靠性，牺牲了数据包的传输速度，因为“三次握手”和“数据包校验机制”等把传输过程中的数据包的数量提高了一倍。</p><h2 id="http-协议" tabindex="-1">HTTP 协议 <a class="header-anchor" href="#http-协议" aria-label="Permalink to &quot;HTTP 协议&quot;">​</a></h2><p>HTTP协议（应用层）是建立在TCP（传输层）连接的基础之上，<strong>HTTP是一种允许浏览器向服务器获取资源的协议，是Web的基础</strong></p><p><img src="'+r+'" alt="HTTP请求"></p><p><strong>浏览器发起HTTP请求流程</strong></p><ol><li>构建请求</li><li>查找缓存 <ul><li>浏览器中查找是否有缓存，如果已有缓存就会拦截请求并结束，返回缓存的资源</li></ul></li><li>准备IP地址和端口 <ul><li>通过DNS（域名系统）找到网站域名的映射ip地址。</li><li>拿到IP之后就需要获取端口号，通常情况是url没有明确知名则默认80</li></ul></li><li>等待TCP队列 <ul><li>Chrome有个机制，同一个域名最多只能建立6个TCP连接，多余的请求会进入排队等待状态</li></ul></li><li>建立TCP连接 <ul><li>和服务器进行TCP连接（三次握手）</li></ul></li><li>发送HTTP请求 <ul><li>发送HTTP数据给服务器，首先向服务器发送请求行（请求方式、请求URI、HTTP协议版本），告诉服务器请求方式、需要什么资源或数据</li><li>发送完请求行之后，还要以请求头形式发送其他一些信息（浏览器信息、cookie信息等）</li></ul></li></ol><p><strong>服务器端处理HTTP请求流程</strong></p><ol><li>返回请求 <ul><li>服务器返回数据给浏览器，可以使用命令查看<code>curl -i https://www.baidu.com/</code></li><li>服务器首先会返回响应行（协议版本和状态码）</li><li>随后服务器会返回响应头（服务器信息、返回数据类型、服务器要在客户端保存的cookie信息）</li><li>响应头之后返回响应体，包括资源或数据</li></ul></li><li>断开连接 <ul><li>一旦服务器向客户端返回了请求数据，它就要关闭TCP连接</li><li>如果浏览器或者服务器头信息中加入了<code>Connection:Keep-Alive </code>，可以继续通过这个TCP连接发送数据，保持连接可以省去下次请求时要建立的时间</li></ul></li><li>重定向 <ul><li>响应行返回状态码301就是告诉浏览器要重定向到另一个网址，网址包含在响应头的Location字段中</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">第一次打开站点速度更快</p><p>因为第一次加载页面过程中，缓存了一些耗时数据</p><p>比如DNS缓存和页面资源缓存，其中页面缓存是通过响应头的<code>Cache-Control</code>字段设置一个缓存时间，如果缓存过期，请求头会增加一个<code>If-None-Match</code>字段，服务端收到后，如果请求的资源没有没有更新就返回304，如果更新了就返回最新的资源</p><p>浏览器处理缓存过程：</p><p><img src="'+s+'" alt="缓存"></p></div><div class="info custom-block"><p class="custom-block-title">登陆状态如何保持</p><p>登陆信息用POST方法提交到服务器，服务器验证后会生成一段标识用户身份的字符串，把字符串写到响应头Set-Cookie字段里</p><p>浏览器会把这个字段的信息保存本地，当浏览器再次发起HTTP请求时，浏览器会把Cookie通过请求头发给服务器</p><p>服务器接收请求头的Cookie之后,当查到包含用户身份的字符串时就查询后台并判断该用户的登陆状态</p></div>',24),P=[c];function T(n,_,u,d,C,h){return o(),i("div",null,P)}const g=l(p,[["render",T]]);export{b as __pageData,g as default};
